LOCK TABLES `faqs` WRITE;
/*!40000 ALTER TABLE `faqs` DISABLE KEYS */;
INSERT INTO `faqs` VALUES (1,'Apa itu Sistem Penjaminan Mutu Internal (SPMI)?','SPMI adalah kegiatan sistemik penjaminan mutu pendidikan tinggi oleh setiap perguruan tinggi secara otonom untuk mengendalikan dan meningkatkan penyelenggaraan pendidikan tinggi secara berencana dan berkelanjutan.','SPMI',1,1,'2026-10-01 04:20:17'),(2,'Apa perbedaan SPMI dan SPME (Akreditasi)?','SPMI dijalankan secara internal oleh perguruan tinggi, sedangkan SPME (Sistem Penjaminan Mutu Eksternal) dilakukan oleh lembaga eksternal seperti BAN-PT atau LAM melalui proses akreditasi.','SPMI',2,1,'2026-10-01 04:20:17'),(3,'Apa siklus utama dalam SPMI di UNIKA?','Siklus SPMI berpedoman pada PPEPP: Penetapan Standar, Pelaksanaan Standar, Evaluasi Pelaksanaan Standar, Pengendalian Pelaksanaan Standar, dan Peningkatan Standar Pendidikan Tinggi.','SPMI',3,1,'2026-10-01 04:20:17'),(4,'Kapan Audit Mutu Internal (AMI) dilaksanakan?','AMI dilaksanakan secara berkala setiap tahun akademik untuk memastikan ketercapaian dan kepatuhan standar mutu pada setiap program studi dan unit kerja.','AMI',4,1,'2026-10-01 04:20:17'),(5,'Bagaimana cara mengajukan permohonan kunjungan studi banding ke LPM UNIKA?','Permohonan dapat diajukan secara resmi melalui menu Layanan > Kunjungan & Studi Banding dengan mengisi formulir pengajuan dan melampirkan surat permohonan resmi institusi.','Layanan',5,1,'2026-10-01 04:20:17'),(6,'Apa status akreditasi institusi UNIKA Soegijapranata saat ini?','Universitas Katolik Soegijapranata terakreditasi UNGGUL oleh Badan Akreditasi Nasional Perguruan Tinggi (BAN-PT).','Akreditasi',1,1,'2026-10-01 08:11:12'),(7,'Bagaimana cara memperoleh legalisir sertifikat akreditasi?','Legalisir sertifikat akreditasi dapat diajukan secara online melalui layanan permohonan LPM atau datang langsung ke Sekretariat LPM.','Akreditasi',2,1,'2026-10-01 08:11:12'),(8,'Apakah seluruh program studi di UNIKA sudah terakreditasi?','Ya, seluruh program studi aktif di Universitas Katolik Soegijapranata telah terakreditasi oleh BAN-PT atau LAM yang berwenang.','Akreditasi',3,1,'2026-10-01 08:11:12');
/*!40000 ALTER TABLE `faqs` ENABLE KEYS */;
UNLOCK TABLES;

