INSERT INTO `glosarium` VALUES (1,'AMI','Audit Mutu Internal','Pedoman SPMI','Audit Mutu Internal','Proses pengujian yang sistematik, mandiri, dan terdokumentasi untuk memastikan pelaksanaan kegiatan di perguruan tinggi sesuai prosedur dan standar.','Pedoman SPMI',1,1,'2026-10-01 04:20:17'),(2,'PPEPP','Penetapan, Pelaksanaan, Evaluasi, Pengendalian, Peningkatan','Permendikbudristek','Penetapan, Pelaksanaan, Evaluasi, Pengendalian, Peningkatan','Siklus penjaminan mutu pendidikan tinggi yang mencakup lima tahapan pokok secara berkelanjutan.','Permendikbudristek',2,1,'2026-10-01 04:20:17'),(3,'SPMI','Sistem Penjaminan Mutu Internal','UU No. 12 Tahun 2012','Sistem Penjaminan Mutu Internal','Kegiatan sistemik penjaminan mutu pendidikan tinggi oleh perguruan tinggi secara otonom.','UU No. 12 Tahun 2012',3,1,'2026-10-01 04:20:17'),(4,'RTM','Rapat Tinjauan Manajemen','Pedoman AMI','Rapat Tinjauan Manajemen','Pertemuan pimpinan untuk mengevaluasi efektivitas penerapan sistem mutu dan menindaklanjuti temuan audit.','Pedoman AMI',4,1,'2026-10-01 04:20:17'),(5,'BAN-PT','Badan Akreditasi Nasional Perguruan Tinggi','Permendikbud','Badan Akreditasi Nasional Perguruan Tinggi','Badan akreditasi yang bertugas melakukan akreditasi perguruan tinggi.','Permendikbud',5,1,'2026-10-01 04:20:17'),(6,'LAM','Lembaga Akreditasi Mandiri','Permendikbud','Lembaga Akreditasi Mandiri','Lembaga yang dibentuk masyarakat atau profesi untuk melakukan akreditasi program studi.','Permendikbud',6,1,'2026-10-01 04:20:17');
