ngevaluasi Sistem Penjaminan Mutu Internal (SPMI) di lingkungan universitas.","bg_color":"#ffffff","text_color":"#0A192F","padding":"normal","is_visible":true},{"id":"block_profil_visi_misi","type":"profil_visi_misi","badge":"Arah & Komitmen","title":"Visi, Misi & Tujuan LPM UNIKA","bg_color":"#ffffff","text_color":"#0A192F","padding":"normal","is_visible":true},{"id":"block_profil_tugas_fungsi","type":"profil_tugas_fungsi","badge":"Landasan Operasional","title":"Tugas dan Fungsi","bg_color":"#F8FAFC","text_color":"#0A192F","padding":"normal","is_visible":true},{"id":"block_profil_struktur","type":"profil_struktur","badge":"Struktur & Tim","title":"Struktur Organisasi LPM","bg_color":"#F8F9FA","text_color":"#0A192F","padding":"normal","is_visible":true}]','2026-09-24 03:01:03'),(29,'Sistem Penjaminan Mutu Internal (SPMI)','spmi','spmi.php','SPMI','Kebijakan, manual, standar mutu, dan formulir pelaksanaan siklus PPEPP.','publish',1,'main','Sistem Penjaminan Mutu Internal (SPMI)','default',NULL,3,NULL,'[{"id":"block_spmi_pengantar","type":"spmi_pengantar","badge":"Pengantar Mutu","title":"Mengenal SPMI di UNIKA","subtitle":"Sistem Penjaminan Mutu Internal (SPMI) Universitas Katolik Soegijapranata merupakan kegiatan sistemik penjaminan mutu pendidikan tinggi yang dilaksanakan secara mandiri oleh universitas untuk mengendalikan dan meningkatkan penyelenggaraan pendidikan tinggi secara berencana dan berkelanjutan.","bg_color":"#ffffff","text_color":"#0A192F","padding":"normal","is_visible":true},{"id":"block_spmi_ppepp","type":"spmi_ppepp","badge":"Alur Kerja Mutu","title":"Siklus PPEPP SPMI","bg_color":"#F8F9FA","text_color":"#0A192F","padding":"normal","is_visible":true},{"id":"block_spmi_kemendikti","type":"spmi_kemendikti","badge":"Publikasi & Pelaporan","title":"Hasil SPMI Kemendikti Saintek","bg_color":"#f1f5f9","text_color":"#0A192F","padding":"normal","is_visible":true},{"id":"block_spmi_dokumen","type":"spmi_dokumen","badge":"Berkas Resmi","title":"Dokumen Mutu 