DROP TABLE IF EXISTS `pemeringkatan`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pemeringkatan` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `judul` varchar(255) NOT NULL,
  `lembaga` varchar(150) NOT NULL,
  `kategori` enum('lokal','nasional','internasional') NOT NULL DEFAULT 'nasional',
  `peringkat` varchar(100) DEFAULT NULL,
  `peringkat_dari` varchar(100) DEFAULT NULL,
  `badge_teks` varchar(100) DEFAULT NULL,
  `warna` varchar(30) DEFAULT NULL,
  `deskripsi` text DEFAULT NULL,
  `link_url` varchar(500) DEFAULT NULL,
  `file_sertifikat` varchar(255) DEFAULT NULL,
  `tahun` varchar(20) NOT NULL DEFAULT '2026',
  `urutan` int(11) NOT NULL DEFAULT 1,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_kategori` (`kategori`),
  KEY `idx_urutan` (`urutan`),
  KEY `idx_is_active` (`is_active`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4;
