INSERT INTO `pemeringkatan` VALUES (1,'EduRank: PTS Nomor 1 di Kota Semarang','EduRank.org & Espos.id','lokal','#1','PTS di Kota Semarang','PTS Terbaik di Semarang 2026',NULL,'Berdasarkan rilis pemeringkatan EduRank 2026 yang diwartakan Espos.id, Soegijapranata Catholic University (SCU) kembali mengukuhkan dominasinya sebagai Perguruan Tinggi Swasta (PTS) nomor satu di Kota Semarang dengan keunggulan kinerja riset 45%, keunggulan non-akademik/reputasi web 45%, dan dampak alumni 10%.','https://news.espos.id/masih-nomor-satu-di-semarang-scu-juga-masuk-100-besar-pts-terbaik-di-indonesia-2208781','','2026',1,1,'2026-10-01 15:38:19','2026-10-01 15:38:19'),(2,'Suara Merdeka: Kampus Swasta Terbaik di Semarang','Suara Merdeka','lokal','Top Tier','Kota Semarang','Rujukan Utama Camaba 2026',NULL,'Ulasan komprehensif Suara Merdeka menempatkan SCU dalam daftar jajaran kampus swasta terbaik dan terfavorit di Kota Semarang tahun 2026 sebagai referensi utama calon mahasiswa baru dengan reputasi mutu akademik unggul dan fasilitas berstandar tinggi.','https://www.suaramerdeka.com/pendidikan/0417103643/daftar-6-kampus-swasta-terbaik-di-semarang-tahun-2026-referensi-mantap-buat-camaba','','2026',2,1,'2026-10-01 15:38:19','2026-10-01 15:38:19'),(3,'uniRank: Daftar Universitas Terkemuka di Jawa Tengah','uniRank (University Ranking)','lokal','Top Ranked','55 Kampus Jawa Tengah','uniRank Official 2026',NULL,'Pemeringkatan resmi uniRank 2026 yang mengevaluasi 55 perguruan tinggi terakreditasi di Jawa Tengah, menilai keterkenalan institusi, validitas perizinan, dan mutu penyelenggaraan pendidikan tinggi.','https://www.unirank.org/id/central-java/a-z/','','2026',3,1,'2026-10-01 15:38:19','2026-10-01 15:38:19'),(4,'EduRank: Peringkat Universitas di Kota Semarang','EduRank.org','lokal','#3','of 14 Kampus Semarang','EduRank Official 2026',NULL,'Peringkat perguruan tinggi terkemuka di Kota Semarang berdasarkan luaran riset akademik dan reputasi institusi.','https://edurank.org/uni/soegijapranata-catholic-university/rankings/','','2026',4,1,'2026-10-01 15:38:19','2026-10-01 15:38:19'),(5,'EduRank: 100 Besar Kampus Terbaik di Indonesia','EduRank.org','nasional','Top 100','Nasional (Negeri & Swasta)','100 Besar Kampus Terbaik Indonesia',NULL,'SCU berhasil menembus jajaran 100 besar perguruan tinggi terbaik di Indonesia (kategori universitas negeri maupun swasta) versi EduRank 2026, ditopang oleh produktivitas publikasi ilmiah, sitasi riset, dan prestasi non-akademik.','https://news.espos.id/masih-nomor-satu-di-semarang-scu-juga-masuk-100-besar-pts-terbaik-di-indonesia-2208781','','2026',1,1,'2026-10-01 15:38:19','2026-10-01 15:38:19'),(6,'Entrepreneurial Marketing Campus for Impact','Marketeers & MCorp (Indonesia Marketing Festival 2026)','nasional','Awardee 2026','Indonesia Marketing Festival ke-14','Marketeers Official 2026',NULL,'Penghargaan bergengsi dari Marketeers dan MCorp pada ajang The 14th Annual Indonesia Marketing Festival 2026 atas peran aktif SCU dalam mengimplementasikan nilai Entrepreneurial Marketing: Creativity, Innovation, Entrepreneurship, and Leadership di lingkungan kampus.','https://www.marketeers.com','sertifikat_marketing_campus_for_impact_2026.pdf','2026',2,1,'2026-10-01 15:38:19','2026-10-01 15:38:19'),(7,'EduRank: Peringkat Universitas di Indonesia','EduRank.org','nasional','#65','of 562 Kampus Indonesia','EduRank Official 2026',NULL,'Akreditasi Unggul dari Badan Akreditasi Nasional Perguruan Tinggi dan menempati peringkat ke-65 dari 562 perguruan tinggi se-Indonesia berdasarkan data EduRank.org.','https://edurank.org/uni/soegijapranata-catholic-university/rankings/','','2026',3,1,'2026-10-01 15:38:19','2026-10-01 15:38:19'),(8,'AD Scientific Index: World Scientist & University Rankings','AD Scientific Index','internasional','World Ranked','24.200 Institusi Global','AD Scientific Index 2026',NULL,'Pemeringkatan internasional berbasis kinerja ilmuwan dan peneliti institusi (metrik Total H-Index, i10-Index, dan Sitasi publikasi ilmiah) yang memetakan kontribusi riset para akademisi SCU di kancah global dan Asia.','https://adscientificindex.com/university/universitas-katolik-soegijapranata/10171/','','2026',1,1,'2026-10-01 15:38:19','2026-10-01 15:38:19'),(9,'uniRank: Global & National University Ranking Profile','uniRank World Universities','internasional','Certified','World Directory','uniRank Certified 2026',NULL,'Profil pemeringkatan internasional uniRank yang memuat evaluasi reputasi web independen, akreditasi program studi institusi, serta keterbukaan informasi akademik bagi komunitas internasional.','https://www.unirank.org/id/uni/soegijapranata-catholic-university/','','2026',2,1,'2026-10-01 15:38:19','2026-10-01 15:38:19'),(10,'UI GreenMetric: World\'s Most Sustainable University','UI GreenMetric','internasional','#1398','World','UI GreenMetric Official 2025',NULL,'Peringkat World\'s Most Sustainable University & kampus hijau di Kota Semarang dalam pengelolaan keberlanjutan dan lingkungan ramah energi.','https://greenmetric.ui.ac.id','sertifikat_ui_greenmetric_2025.webp','2025',3,1,'2026-10-01 15:38:19','2026-10-01 15:38:19');
