INSERT INTO `pengaturan` VALUES ('akred_card_badge','STATUS RESMI'),('akred_card_desc','Berdasarkan Keputusan Badan Akreditasi Nasional Perguruan Tinggi (BAN-PT) untuk Institusi Universitas Katolik Soegijapranata.'),('akred_card_title','TERAKREDITASI'),('akred_institusi_file','2023_Sertifikat_Akreditasi_ISK_AIPT_UNIKA_Unggul.pdf'),('akred_institusi_peringkat','UNGGUL'),('alamat','Ruang Lembaga Penjaminan Mutu\nGedung Thomas Aquinas Lantai 5\nKampus Universitas Katolik Soegijapranata\nJalan Pawiyatan Luhur IV/1 Bendan Duwur Semarang 50234'),('ami_siklus_banner_desc','Rangkaian terintegrasi tahapan Siklus 1 hingga Siklus 5 AMI Universitas Katolik Soegijapranata untuk menjamin standar mutu pendidikan tinggi yang unggul dan berkelanjutan.'),('ami_siklus2_desc','Portal sistem e-AMI untuk pengisian dokumen evaluasi diri (DED), pengunggahan berkas bukti fisik ketercapaian standar mutu SPMI, dan sinkronisasi data akademik Program Studi.'),('ami_siklus2_judul','e-AMI: Siklus 2 - Pengisian Dokumen Kinerja (DED)'),('ami_siklus2_status','coming_soon'),('ami_siklus2_url','https://e-ami.unika.ac.id/siklus2'),('ami_siklus3_desc','Portal kerja auditor mutu internal untuk pelaksanaan desk evaluation, penelaahan bukti sahih indikator kinerja, pencatatan temuan observasi / ketidaksesuaian (KTS), dan penyusunan daftar tilik sebelum visitasi.'),('ami_siklus3_judul','e-AMI: Siklus 3 - Audit Dokumen (Desk Evaluation)'),('ami_siklus3_status','coming_soon'),('ami_siklus3_url','https://e-ami.unika.ac.id/siklus3'),('ami_stage1_desc','Penetapan jadwal siklus audit, penunjukan tim auditor tersertifikasi, dan pengiriman surat pemberitahuan ke seluruh auditee.'),('ami_stage1_title','Perencanaan & Sosialisasi'),('ami_stage2_desc','Program Studi dan Unit Kerja mengisi instrumen evaluasi diri dan mengunggah bukti fisik pendukung pada sistem e-AMI.'),('ami_stage2_title','Pengisian Dokumen Kinerja (DED)'),('ami_stage3_desc','Auditor memeriksa kecukupan dan kesesuaian dokumen bukti kerja terhadap standar mutu sebelum pelaksanaan visitasi.'),('ami_stage3_title','Audit Dokumen (Desk Evaluation)'),('ami_stage4_desc','Auditor melakukan verifikasi langsung, wawancara auditee, konfirmasi temuan KTS (Ketidaksesuaian), dan penandatanganan berita acara..'),('ami_stage4_title','Audit Lapangan Visitasi'),('ami_stage5_desc','Penyampaian rekapitulasi temuan audit kepada Rektorat dan Pimpinan Unit untuk perumusan Rencana Tindak Lanjut (RTL).'),('ami_stage5_title','Rapat Tinjauan Manajemen RTM)'),('email','lpm@unika.ac.id'),('feedback_kunjungan_aktif','1'),('feedback_kunjungan_durasi_jam','24'),('feedback_kunjungan_judul','Kuesioner Umpan Balik Kunjungan Mitra Institusi'),('footer_desc','Lembaga Penjaminan Mutu Universitas Katolik Soegijapranata berkomitmen untuk mewujudkan mutu pendidikan tinggi yang unggul, berkelanjutan, dan berdaya saing global.'),('greenmetric_badge','UI GREENMETRIC 2024'),('greenmetric_desc','Komitmen Universitas Katolik Soegijapranata dalam pembangunan kampus berkelanjutan, pengelolaan energi hijau ramah lingkungan, dan pelestarian alam terukur secara global.'),('greenmetric_rank','#84'),('greenmetric_scope','Peringkat Nasional (Indonesia)'),('greenmetric_title','World University Rankings Network'),('hero_btn_link','spmi.php'),('hero_btn_text','Akses Dokumen SPMI'),('hero_btn2_link','profil.php'),('hero_btn2_text','Profil Lembaga'),('hero_desc','Mewujudkan tata kelola penjaminan mutu pendidikan tinggi yang unggul, terencana, dan berkelanjutan.'),('hero_tagline','GROW WITH QUALITY, SERVE WITH HEART'),('hero_title','Lembaga Penjaminan Mutu Unika'),('hero_welcome_text','Selamat datang di'),('jam_kerja','Senin ??? Jumat: 08.00 ??? 16.00 WIB'),('layout_penghargaan','slider'),('maps_embed_url','https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3960.0927505866!2d110.41095357403498!3d-7.044023469178!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2e708c6c8dbc7c2d%3A0x6e9c0e63f52dc05!2sSoegijapranata%20Catholic%20University!5e0!3m2!1sen!2sid!4v1700000000000!5m2!1sen!2sid'),('pelatihan_email_kontak','lpm@unika.ac.id'),('pelatihan_hero_desc','Program Pelatihan, Bimbingan Teknis, Sertifikasi Auditor Mutu Internal (AMI), dan Klinik Akreditasi Perguruan Tinggi Mitra'),('pelatihan_hero_title','Info Pelatihan Lembaga Penjaminan Mutu'),('pelatihan_narasi_lengkap','Lembaga Penjaminan Mutu (LPM) Universitas Katolik Soegijapranata berkomitmen mengawal dan menumbuhkan budaya mutu pendidikan tinggi yang unggul, berkelanjutan, dan berdaya saing global.\n\nBerbekal pengalaman mengawal akreditasi institusi UNGGUL serta amanah Kementerian sebagai pelaksana Program Asuh Perguruan Tinggi Unggul selama bertahun-tahun yang telah sukses mendampingi puluhan perguruan tinggi dan program studi di Indonesia, LPM UNIKA secara konsisten menyelenggarakan berbagai program pelatihan, bimbingan teknis, dan sertifikasi penjaminan mutu terstruktur bagi perguruan tinggi mitra, fakultas, serta lembaga pendidikan.\n\nProgram pelatihan difasilitasi langsung oleh para pakar penjaminan mutu, asesor BAN-PT/LAM bersertifikasi nasional, serta auditor mutu internal berpengalaman. Seluruh kurikulum dan materi dirancang aplikatif, berbasis studi kasus riil tata kelola kampus, dan selaras dengan regulasi Permendikbudristek No. 53 Tahun 2023 tentang Penjaminan Mutu Pendidikan Tinggi serta standar instrumen akreditasi terkini.'),('pemeringkatan_color_internasional','#1E3A8A'),('pemeringkatan_color_lokal','#0D9488'),('pemeringkatan_color_nasional','#991B1B'),('portal_eppepp_badge','SIKLUS MUTU PPEPP'),('portal_eppepp_cs_desc','Pelaksanaan dan evaluasi sistem e-PPEPP akan diaktifkan sesuai jadwal.'),('portal_eppepp_cs_title','Tautan Sistem e-PPEPP Belum Dibuka'),('portal_eppepp_desc','Sistem informasi elektronik implementasi, evaluasi pelaksanaan, dan pengendalian tahapan siklus PPEPP secara berkesinambungan.'),('portal_eppepp_name','Portal E-PPEPP'),('portal_eppepp_status','coming_soon'),('portal_eppepp_url','https://e-ppepp.unika.ac.id'),('portal_sista_badge','STANDAR AKADEMIK'),('portal_sista_cs_desc','Pemantauan dan pelaporan siklus PPEPP diaktifkan sesuai jadwal.'),('portal_sista_cs_title','Tautan Sistem SISTA Belum Dibuka'),('portal_sista_desc','Pemantauan & pelaporan siklus PPEPP, perumusan capaian, bukti dukung pelaksanaan, dan rencana tindak lanjut termonitor secara digital terintegrasi.'),('portal_sista_name','Portal SISTA'),('portal_sista_status','active'),('portal_sista_url','https://sista.unika.ac.id'),('portal_spmi_badge','PELAPORAN NASIONAL'),('portal_spmi_cs_desc','Pelaporan evaluasi pelaksanaan penjaminan mutu akan diaktifkan sesuai jadwal.'),('portal_spmi_cs_title','Tautan Sistem SPMI Kemendikti Belum Dibuka'),('portal_spmi_desc','Rekapitulasi dan pelaporan evaluasi pelaksanaan penjaminan mutu perguruan tinggi secara berkala kepada Kementerian Pendidikan Tinggi, Sains, dan Teknologi.'),('portal_spmi_name','Portal SPMI Kemendikti'),('portal_spmi_status','active'),('portal_spmi_url','https://spmi.kemdiktisaintek.go.id/auth/login'),('profil_fungsi','Penyediaan data pelaksanaan sistem penjaminan mutu internal sebagai bahan penyusunan kebijakan Universitas.\nPemberian rekomendasi dan/atau usulan kepada Rektor dalam penyelenggaraan dan pengembangan SPMI.\nPengkajian dan pengembangan dokumen SPMI maupun dokumen mutu lainnya.\nPengkoordinasian, pelaksanaan dan monitoring SPMI.\nPengkoordinasian penyusunan prosedur sistem mutu, instruksi kerja maupun dokumen mutu lainnya.\nPelaksanaan dan monitoring Audit Mutu Internal (AMI).\nPengkoordinasian, pembimbingan teknis, monitoring dan evaluasi pelaksanaan proses akreditasi perguruan tinggi (APT) dan program studi (APS).\nPengawasan pelaksanaan Rapat Tinjauan Manajemen.'),('profil_misi','Menyelenggarakan penyediaan data yang sahih dan valid di bidang penjaminan mutu melalui sistem monitoring dan evaluasi yang terstruktur, terencana dan berkelanjutan.\r\nMenyelenggarakan sistem penjaminan mutu yang efektif, partisipatif, dan dihidupi oleh seluruh sivitas akademika dan tenaga kependidikan.\r\nMembangun budaya mutu melalui sinergi, pendampingan, dan kolaborasi dengan gugus mutu serta para pemangku kepentingan.\r\nMemfasilitasi pengembangan kapasitas dan kompetensi sumber daya manusia di bidang penjaminan mutu.\r\nMendorong peningkatan mutu berkelanjutan untuk mendukung pencapaian visi dan reputasi Universitas.'),('profil_tentang_judul','Lembaga Penjaminan Mutu Universitas Katolik Soegijapranata'),('profil_tentang_teks1','Universitas Katolik Soegijapranata sudah mulai melaksanakan penjaminan mutu secara sistematis sejak tahun 2005 dengan dibentuknya Kantor Jaminan Mutu (KJM) berdasarkan Keputusan Rektor No: E.2/1467/Kep/IV/2005, yang kemudian diubah menjadi Lembaga Jaminan Mutu Pendidikan (LJMP) berdasarkan Keputusan Rektor No: E.2/2572/ Kep/VIII/2005.\r\n\r\nPada tahun 2013, sesuai dengan Statuta Universitas Katolik Soegijapranata, LJMP diubah namanya menjadi Lembaga Penjaminan Mutu (LPM). Awalnya, sistem manajemen mutu yang diterapkan di Unika Soegijapranata yaitu ISO (The International Organization for Standardization) 9001:2000 yang kemudian dikembangkan menjadi ISO 9001:2008 sampai dengan tahun akademik 2015/2016.\r\nMulai tahun akademik 2016/2017, Universitas Katolik Soegijapranata mengembangkan Sistem Penjaminan Mutu Internal (SPMI) sebagaimana diwajibkan Permenristekdikti No. 62 Tahun 2016 tentang Sistem Penjaminan Mutu Pendidikan Tinggi (SPM Dikti) berdasarkan Permendikbud No. 3 Tahun 2020 tentang Standar Nasional Pendidikan 10 buku pedoman universitas 2022 - 2023 Tinggi (SN Dikti).'),('profil_tentang_teks2','Dalam perkembangannya, penjaminan mutu dilakukan untuk merekam dan memantau secara berkelanjutan tentang Penetapan, Pelaksanaan, Evaluasi, Pengendalian dan Peningkatan (PPEPP) Standar SPMI. Implementasi siklus SPM Universitas Katolik Soegijapranata didasarkan pada acuan Standar Nasional Pendidikan Tinggi (SN Dikti) dan standar Pendidikan Tinggi yang ditetapkan oleh Universitas Katolik Soegijapranata. Selanjutnya Unit Pengelola Program Studi (UPPS) menyusun dan menjalankan rencana strategis dan rencana operasional dengan mengacu pada standar akademik Universitas Katolik Soegijapranata. Untuk evaluasi pelaksanaan standar, LPM bekerjasama dengan Gugus Penjaminan Mutu (GPM) memonitor pelaksanaan standar dan dilakukan koordinasi untuk membahas temuan-temuan yang muncul di masing-masing fakultas/prodi.\r\n\r\nSebagai bagian dari siklus penjaminan mutu internal, Universitas Katolik Soegijapranata juga melakukan benchmarking untuk meningkatkan mutu implementasi SPMI. Komitmen Universitas Katolik Soegijapranata dalam menjalankan SPMI telah mengantarkan pada pencapaian hibah ???Program Asuh Perguruan Tinggi Unggul??? selama tiga tahun (2017, 2018 dan 2019) dan telah mendampingi/mengasuh lebih dari 60 program studi di luar Universitas Katolik Soegijapranata menuju program studi unggul. Pada bulan April tahun 2023, Universitas Katolik Soegijapranata berhasil mendapatkan Peringkat Akreditasi UNGGUL berdasarkan SK BAN PT No. 263/SK/BAN-PT/Ak.KP/PT/IV/2023 dan seluruh Program Studi telah terakreditasi.'),('profil_tugas','Sesuai Peraturan Universitas Katolik Soegijapranata No. 01/E.2/Per-UKS/XI/2019 tentang Organisasi dan Tata Kelola Universitas Katolik Soegijapranata, LPM bertugas merencanakan, melaksanakan, mengevaluasi dan mengembangkan sistem penjaminan mutu.'),('profil_tujuan','Terwujudnya sistem penjaminan mutu yang terstruktur, terencana, efektif dan berkelanjutan.\r\nTerwujudnya sistem monitoring, evaluasi, dan penyediaan data mutu yang sahih, valid dan terintegrasi sebagai dasar pengambilan keputusan.\r\nMeningkatnya kapasitas dan kompetensi sumber daya manusia di bidang penjaminan mutu.\r\nTerwujudnya sistem penjaminan mutu berbasis teknologi informasi yang efektif, efisien dan terintegrasi.\r\nTerwujudnya budaya mutu yang dihidupi oleh seluruh sivitas akademika dan tenaga kependidikan.\r\nMeningkatnya efektivitas peningkatan mutu berkelanjutan dalam mendukung pencapaian visi dan reputasi Universitas.'),('profil_visi','Terwujudnya budaya mutu melalui sistem penjaminan mutu yang mendukung pencapaian visi Universitas Katolik Soegijapranata.'),('sambutan_foto',''),('sambutan_instansi','Universitas Katolik Soegijapranata'),('sambutan_jabatan','Kepala Lembaga Penjaminan Mutu'),('sambutan_nama','Stefani Lily Indarto, SE., MM., Ak., CA., CPA.'),('sambutan_teks','Puji syukur kepada Tuhan Yang Maha Esa atas berkat dan rahmat-Nya, sehingga Lembaga Penjaminan Mutu (LPM) Universitas Katolik Soegijapranata dapat terus menjalankan peran strategisnya dalam menjamin dan meningkatkan mutu pendidikan tinggi.\n\nLPM UNIKA hadir sebagai motor penggerak budaya mutu di lingkungan Universitas, dengan misi utama merancang, memantau, dan mengevaluasi pelaksanaan Sistem Penjaminan Mutu Internal (SPMI) secara konsisten melalui siklus PPEPP ??? Penetapan, Pelaksanaan, Evaluasi, Pengendalian, dan Peningkatan Standar Mutu.\n\nKami mengundang seluruh civitas akademika dan pemangku kepentingan untuk bersama-sama membangun ekosistem pendidikan yang berkualitas, inovatif, dan berdampak bagi masyarakat.'),('site_subtitle','Universitas Katolik Soegijapranata'),('site_title','LPM UNIKA'),('spmi_chart_badge','Siklus Penjaminan Mutu Berkelanjutan'),('spmi_chart_desc','Implementasi penjaminan mutu di Universitas Katolik Soegijapranata berlandaskan pada 5 tahap siklus berkelanjutan (PPEPP). Klik salah satu lingkaran siklus di bawah ini untuk menelaah penjelasan rinci setiap tahapannya.'),('spmi_chart_title','Siklus PPEPP SPMI Interaktif'),('stat_akreditasi','Unggul'),('stat_ami','88'),('stat_ppepp','92'),('stat_prodi','27'),('stat_standar','95'),('stat_tahun','40'),('telepon','024-8441555 Ext 1473'),('website_url','https://www.unika.ac.id');
/*!40000 ALTER TABLE `pengaturan` ENABLE KEYS */;
UNLOCK TABLES;

