INSERT INTO `spmi_ppepp_stages` VALUES (1,1,'P','Penetapan','TAHAP 1 DARI 5 • SIKLUS SPMI','Penetapan Standar Dikti (P)','Penetapan Standar Dikti;','#C0392B','Tahap awal perumusan, penyelarasan, dan penetapan seluruh tolok ukur standar mutu akademik, non-akademik, serta standar ciri khas Universitas Katolik Soegijapranata yang disusun melampaui Standar Nasional Pendidikan Tinggi (SN Dikti).','PROSEDUR OPERASIONAL:','Penyusunan draf standar mutu bersama tim pakar LPM dan UPPS.\nUji publik dan review komprehensif bersama Gugus Penjaminan Mutu (GPM).\nPemberian pertimbangan dan persetujuan formal oleh Senat Akademik Universitas.\nPenetapan resmi pemberlakuan standar melalui Surat Keputusan Rektor.','DOKUMEN TERKAIT:','Kebijakan SPMI, Manual Penetapan Standar, dan Buku Standar SPMI (Pendidikan, Riset, PkM, & Identitas).','PENANGGUNG JAWAB:','Rektor, Senat Akademik Universitas, & LPM','Dokumen Terkait','#dokumen-spmi','Standar Mutu UNIKA Soegijapranata','2026-10-01 15:38:19'),(2,2,'P','Pelaksanaan','TAHAP 2 DARI 5 • SIKLUS SPMI','Pelaksanaan Standar Dikti (P)','Pelaksanaan Standar Dikti;','#689F38','Tahap implementasi seluruh indikator capaian standar yang telah disahkan ke dalam operasional tridharma perguruan tinggi dan tata kelola unit kerja di lingkungan kampus UNIKA.','PROSEDUR OPERASIONAL:','Sosialisasi menyeluruh isi standar mutu kepada dosen, tendik, dan mahasiswa.\nPenerapan SOP operasional dalam perkuliahan, bimbingan, penelitian, dan pengabdian.\nPenyusunan dan pengarsipan portofolio pembelajaran serta bukti fisik ketercapaian standar.\nPencatatan real-time melalui sistem informasi akademik dan portal terpadu kampus.','DOKUMEN TERKAIT:','SOP Pelaksanaan, Modul Perkuliahan, Rencana Pembelajaran (RPS), Kontrak Kinerja Unit, dan Bukti Tridharma.','PENANGGUNG JAWAB:','Dekan, Ketua Program Studi, Kepala Lembaga/Biro, Dosen, & Tendik','Dokumen Terkait','#dokumen-spmi','Standar Mutu UNIKA Soegijapranata','2026-10-01 15:38:19'),(3,3,'E','Evaluasi','TAHAP 3 DARI 5 • SIKLUS SPMI','Evaluasi (Pelaksanaan) Standar Dikti (E)','Evaluasi (Pelaksanaan) Standar Dikti;','#6A4C93','Tahap pemantauan, pengukuran, dan pengujian berkala terhadap kesesuaian pelaksanaan kegiatan dengan tolok ukur standar mutu, guna mendeteksi secara dini potensi hambatan maupun ketidaksesuaian.','PROSEDUR OPERASIONAL:','Pengisian Dokumen Evaluasi Diri (DED) berbasis data riil oleh UPPS/Unit.\nPelaksanaan Audit Mutu Internal (AMI) terjadwal oleh auditor internal bersertifikat.\nVisitasi lapangan, wawancara auditee, dan uji petik bukti dukung fisik/digital.\nPenyusunan Laporan Hasil Audit Mutu, rekapitulasi temuan KTS, dan potensi risiko.','DOKUMEN TERKAIT:','Instrumen Audit Mutu Internal (AMI), Dokumen Evaluasi Diri (DED), Laporan Temuan KTS, dan Survei Kepuasan.','PENANGGUNG JAWAB:','Kepala Pusat AMI, Tim Auditor Internal Tersertifikasi, & Auditee','Dokumen Terkait','#dokumen-spmi','Standar Mutu UNIKA Soegijapranata','2026-10-01 15:38:19'),(4,4,'P','Pengendalian','TAHAP 4 DARI 5 • SIKLUS SPMI','Pengendalian (Pelaksanaan) Standar Dikti (P)','Pengendalian (Pelaksanaan) Standar Dikti; dan','#00838F','Tahap analisis dan perumusan tindakan korektif terhadap temuan evaluasi melalui forum resmi Rapat Tinjauan Manajemen (RTM) agar penyimpangan segera teratasi dan tidak berulang.','PROSEDUR OPERASIONAL:','Penyusunan Rencana Tindak Lanjut (RTL) dan tenggat waktu perbaikan oleh auditee.\nPenyelenggaraan Rapat Tinjauan Manajemen (RTM) berjenjang (Prodi, Fakultas, Universitas).\nKeputusan pimpinan terkait alokasi sumber daya pendukung percepatan pemenuhan standar.\nVerifikasi dan monitoring penutupan status temuan KTS oleh GPM dan LPM.','DOKUMEN TERKAIT:','Risalah RTM, Lembar Rencana Tindak Lanjut (RTL), Bukti Perbaikan Tindak Lanjut, dan Berita Acara RTM.','PENANGGUNG JAWAB:','Rektor, Wakil Rektor, Dekan Fakultas, Kepala Unit Kerja, & GPM','Dokumen Terkait','#dokumen-spmi','Standar Mutu UNIKA Soegijapranata','2026-10-01 15:38:19'),(5,5,'P','Peningkatan','TAHAP 5 DARI 5 • SIKLUS SPMI','Peningkatan Standar Dikti (P)','Peningkatan Standar Dikti.','#E65100','Tahap menaikkan target atau memperluas kriteria standar mutu yang telah tercapai secara konsisten (kaizen berkelanjutan) agar kualitas institusi terus meningkat menuju standar internasional.','PROSEDUR OPERASIONAL:','Kajian kelayakan terhadap standar yang telah berhasil dipenuhi secara penuh dan konsisten.\nBenchmarking mutu ke institusi mitra terbaik di tingkat nasional dan internasional.\nRevisi rumusan indikator capaian standar menjadi lebih tinggi dan adaptif masa depan.\nPengesahan standar edisi terbaru sebagai titik awal siklus Penetapan berikutnya.','DOKUMEN TERKAIT:','Naskah Rekomendasi Peningkatan Mutu, Laporan Studi Banding/Benchmarking, dan Draf Revisi Standar Baru.','PENANGGUNG JAWAB:','Rektor, Senat Akademik Universitas, Dewan Pakar Mutu, & LPM','Dokumen Terkait','#dokumen-spmi','Standar Mutu UNIKA Soegijapranata','2026-10-01 15:38:19');
/*!40000 ALTER TABLE `spmi_ppepp_stages` ENABLE KEYS */;
UNLOCK TABLES;

