INSERT INTO `tim_lpm` VALUES (11,'lpm','Stefani Lily Indarto, SE., MM., Ak., CA., CPA.','Kepala Lembaga Penjaminan Mutu','Pimpinan Lembaga','Memimpin perumusan, pelaksanaan, dan evaluasi kebijakan penjaminan mutu universitas.','1. Memimpin perumusan, pelaksanaan, serta evaluasi kebijakan penjaminan mutu universitas.\r\n2. Mengawal proses Audit Mutu Internal (AMI), akreditasi institusi & prodi, serta pemeringkatan secara berkelanjutan.\r\n3. Memastikan sinergi penjaminan mutu di tingkat universitas, fakultas, program studi, dan unit kerja.\r\n4. Bertanggung jawab langsung kepada Rektor dalam penyelenggaraan Sistem Penjaminan Mutu Internal (SPMI).','tim_6a9fbc8abf989.webp','pimpinan',1,'2026-09-03 03:17:17'),(12,'lpm','Vera Retnowati, ST., MM.','Sekretaris Lembaga Penjaminan Mutu','Manajemen & Tata Kelola','Mengkoordinasikan pengelolaan program kerja, keuangan, dan administrasi dokumen mutu.','1. Mengkoordinasikan pengelolaan program kerja tahunan, anggaran keuangan, dan administrasi lembaga.\r\n2. Memastikan pengarsipan dan pendokumentasian seluruh regulasi, manual, dan standar mutu berjalan tertib.\r\n3. Membantu Kepala LPM dalam pelaksanaan koordinasi dengan unit kerja internal dan pihak eksternal.\r\n4. Memandu operasional sekretariat LPM dan rapat-rapat koordinasi berkala.','tim_6a9fbcb3e3230.webp','sekretaris',2,'2026-09-03 03:17:17'),(13,'lpm','Ir. I.M. Tri Hesti Mulyani, MT.','Ketua Pusat Pengembangan Sistem Penjaminan Mutu','Pengembangan SPMI','Mengembangkan dan merumuskan standar mutu dan dokumen SPMI di lingkungan universitas.','1. Merumuskan dan merevisi dokumen Kebijakan, Manual, Standar, dan Formulir Mutu SPMI.\r\n2. Mendampingi Gugus Penjaminan Mutu (GPM) fakultas/prodi dalam sosialisasi dan implementasi standar mutu.\r\n3. Memantau ketercapaian Indikator Kinerja Utama (IKU) dan Indikator Kinerja Tambahan (IKT).\r\n4. Menyusun rekomendasi peningkatan standar mutu secara berkelanjutan (siklus PPEPP).','tim_6a9fbcfee94dc.webp','koordinator',3,'2026-09-03 03:17:17'),(14,'lpm','dr. Maya Yanuarty, M.Biomed','Ketua Pusat Audit Mutu Internal','Audit Mutu Internal (AMI)','Melaksanakan Audit Mutu Internal (AMI) secara terencana, obyektif, dan terstruktur.','1. Menyusun instrumen, jadwal, dan alokasi tim auditor untuk siklus Audit Mutu Internal (AMI).\r\n2. Memimpin pelaksanaan audit dokumen (Desk Evaluation) dan audit lapangan (Field Evaluation).\r\n3. Mengkoordinasikan Rapat Tinjauan Manajemen (RTM) dan memantau Permintaan Tindakan Koreksi (PTK).\r\n4. Mengelola rekrutmen, pelatihan, dan penyegaran kompetensi Auditor Internal bersertifikat.','tim_6a9fbd3f1f27c.webp','koordinator',4,'2026-09-03 03:17:17'),(15,'lpm','Ir. Lintang Jata Angghita, ST., M.Ling','Ketua Pusat Pemeringkatan','Pemeringkatan & Reputasi','Mengelola strategi peningkatan posisi pemeringkatan perguruan tinggi dan akreditasi.','1. Memetakan kriteria dan indikator pemeringkatan perguruan tinggi nasional dan internasional.\r\n2. Mengumpulkan dan memverifikasi data capaian kinerja universitas untuk submisi lembaga pemeringkat.\r\n3. Mendampingi persiapan borang akreditasi institusi (APT) dan borang akreditasi program studi (APS).\r\n4. Menyusun rekomendasi langkah strategis pemeringkatan kelembagaan kepada pimpinan universitas.','tim_6a9fbd72f32e3.webp','koordinator',5,'2026-09-03 03:17:17'),(16,'lpm','Hermawan, S.M.','Staf Tata Usaha Lembaga Penjaminan Mutu','Administrasi & Kesekretariatan','Mendukung operasional lembaga melalui layanan administrasi dan dokumentasi kegiatan.','1. Menangani surat-menyurat, persuratan dinas, dan pengarsipan fisik & digital LPM.\r\n2. Mengelola operasional kegiatan harian, persiapan sarana rapat, dan pendokumentasian acara.\r\n3. Membantu pengelolaan sistem informasi penjaminan mutu dan pembaruan konten portal web.\r\n4. Melayani kebutuhan administrasi civitas akademika dan pengunjung operasional LPM.','tim_6a9fbd9107352.webp','staf',6,'2026-09-03 03:17:17'),(21,'gpm','Ch. Tri Hardjanti, SE., M.Si','Koordinator GPM FEB','Penjaminan Mutu Fakultas Ekonomi dan Bisnis (FEB)','Mengkoordinasikan pelaksanaan dan penjaminan mutu akademik tingkat fakultas bersama Gugus Penjaminan Mutu.','Merencanakan, memonitor, dan mengevaluasi siklus SPMI (PPEPP) di lingkungan fakultas.\r\nMendampingi proses akreditasi dan pemutakhiran data program studi.\r\nMelakukan audit mutu internal dan tindak lanjut perbaikan mutu akademik fakultas.','tim_6a9fbec6e342a.webp','koordinator',1,'2026-09-08 07:49:44'),(22,'gpm','Dr. Dra. Alberta Rika Pratiwi, M.Si','Koordinator GPM FTP','Penjaminan Mutu Fakultas Teknologi Pertanian (FTP)','Mengkoordinasikan pelaksanaan dan penjaminan mutu akademik tingkat fakultas bersama Gugus Penjaminan Mutu.','Merencanakan, memonitor, dan mengevaluasi siklus SPMI (PPEPP) di lingkungan fakultas.\r\nMendampingi proses akreditasi dan pemutakhiran data program studi.\r\nMelakukan audit mutu internal dan tindak lanjut perbaikan mutu akademik fakultas.','tim_6a9fbf3ce863d.webp','koordinator',2,'2026-09-08 07:49:44'),(23,'gpm','R. B. J. E. Theo Adi Negoro, S.H., MH','Koordinator GPM FHK','Penjaminan Mutu Fakultas Hukum dan Komunikasi (FHK)','Mengkoordinasikan pelaksanaan dan penjaminan mutu akademik tingkat fakultas bersama Gugus Penjaminan Mutu.','Merencanakan, memonitor, dan mengevaluasi siklus SPMI (PPEPP) di lingkungan fakultas.\r\nMendampingi proses akreditasi dan pemutakhiran data program studi.\r\nMelakukan audit mutu internal dan tindak lanjut perbaikan mutu akademik fakultas.','tim_6a9fc3532e2b1.webp','koordinator',3,'2026-09-08 07:49:44'),(24,'gpm','Ir. Budi Santosa, MT.','Koordinator GPM FT','Penjaminan Mutu Fakultas Teknik (FT)','Mengkoordinasikan pelaksanaan dan penjaminan mutu akademik tingkat fakultas bersama Gugus Penjaminan Mutu.','Merencanakan, memonitor, dan mengevaluasi siklus SPMI (PPEPP) di lingkungan fakultas.\r\nMendampingi proses akreditasi dan pemutakhiran data program studi.\r\nMelakukan audit mutu internal dan tindak lanjut perbaikan mutu akademik fakultas.','tim_6a9fc0a8792ee.webp','koordinator',4,'2026-09-08 07:49:44'),(25,'gpm','Dr. Dra. Margaretha Sih Setija Utami, M.Kes.','Koordinator GPM FPSI','Penjaminan Mutu Fakultas Psikologi (FPSI)','Mengkoordinasikan pelaksanaan dan penjaminan mutu akademik tingkat fakultas bersama Gugus Penjaminan Mutu.','Merencanakan, memonitor, dan mengevaluasi siklus SPMI (PPEPP) di lingkungan fakultas.\r\nMendampingi proses akreditasi dan pemutakhiran data program studi.\r\nMelakukan audit mutu internal dan tindak lanjut perbaikan mutu akademik fakultas.','tim_6a9fc1459e59a.webp','koordinator',5,'2026-09-08 07:49:44'),(26,'gpm','dr. To Lidwina Prillya Indra Christyana, M.Biomed','Koordinator GPM FK','Penjaminan Mutu Fakultas Kedokteran (FK)','Mengkoordinasikan pelaksanaan dan penjaminan mutu akademik tingkat fakultas bersama Gugus Penjaminan Mutu.','Merencanakan, memonitor, dan mengevaluasi siklus SPMI (PPEPP) di lingkungan fakultas.\r\nMendampingi proses akreditasi dan pemutakhiran data program studi.\r\nMelakukan audit mutu internal dan tindak lanjut perbaikan mutu akademik fakultas.','tim_6a9fc1eec9ce2.webp','koordinator',6,'2026-09-08 07:49:44'),(27,'gpm','Dr. Dra. Ekawati Marhaenny Dukut, M.Hum.','Koordinator GPM FBS','Penjaminan Mutu Fakultas Bahasa dan Seni (FBS)','Mengkoordinasikan pelaksanaan dan penjaminan mutu akademik tingkat fakultas bersama Gugus Penjaminan Mutu.','Merencanakan, memonitor, dan mengevaluasi siklus SPMI (PPEPP) di lingkungan fakultas.\r\nMendampingi proses akreditasi dan pemutakhiran data program studi.\r\nMelakukan audit mutu internal dan tindak lanjut perbaikan mutu akademik fakultas.','tim_6a9fc20b2be29.webp','koordinator',7,'2026-09-08 07:49:44'),(28,'gpm','Erdhi Widyarto Nugroho, ST., MT.','Koordinator GPM FIKOM','Penjaminan Mutu Fakultas Ilmu Komputer (FIKOM)','Mengkoordinasikan pelaksanaan dan penjaminan mutu akademik tingkat fakultas bersama Gugus Penjaminan Mutu.','Merencanakan, memonitor, dan mengevaluasi siklus SPMI (PPEPP) di lingkungan fakultas.\r\nMendampingi proses akreditasi dan pemutakhiran data program studi.\r\nMelakukan audit mutu internal dan tindak lanjut perbaikan mutu akademik fakultas.','tim_6a9fc187e6860.webp','koordinator',8,'2026-09-08 07:49:44'),(29,'gpm','Dr. Ir. Antonius Ardiyanto, MT.','Koordinator GPM FAD','Penjaminan Mutu Fakultas Arsitektur dan Desain (FAD)','Mengkoordinasikan pelaksanaan dan penjaminan mutu akademik tingkat fakultas bersama Gugus Penjaminan Mutu.','Merencanakan, memonitor, dan mengevaluasi siklus SPMI (PPEPP) di lingkungan fakultas.\r\nMendampingi proses akreditasi dan pemutakhiran data program studi.\r\nMelakukan audit mutu internal dan tindak lanjut perbaikan mutu akademik fakultas.','tim_6a9fc1be5b8d3.webp','koordinator',9,'2026-09-08 07:49:44'),(30,'gpm','Dhiyan Krishna Wardani, ST., M.U.E','Koordinator GPM FITL','Penjaminan Mutu Fakultas Ilmu dan Teknologi Lingkungan (FITL)','Mengkoordinasikan pelaksanaan dan penjaminan mutu akademik tingkat fakultas bersama Gugus Penjaminan Mutu.','Merencanakan, memonitor, dan mengevaluasi siklus SPMI (PPEPP) di lingkungan fakultas.\r\nMendampingi proses akreditasi dan pemutakhiran data program studi.\r\nMelakukan audit mutu internal dan tindak lanjut perbaikan mutu akademik fakultas.','tim_6a9fc1a45f812.webp','koordinator',10,'2026-09-08 07:49:44');
